def odd_length_sum(arr):
    total = 0
    n = len(arr)

    # Iterate over all possible subarrays with odd lengths
    for start in range(n):
        for end in range(start + 1, n + 1):
            length = end - start

            # Check if the current subarray has an odd length
            if length % 2 == 1:
                # Calculate sum of elements from index 'start' to 'end-1'
                for i in range(start, end):
                    total += arr[i]

    return total
